import "server-only";

import { apiBaseUrl } from "@/config/api";
import { ApiError, toApiError } from "@/lib/api/errors";
import { CatalogApi, Configuration, DiscoveryApi, MarketplaceApi } from "@/lib/api/generated/public";

export { ApiError };

/**
 * Server-side clients for the backend's public surface (/api/public/v1). Generated by OpenAPI Generator
 * from backend/openapi/public-v1.json (API_DESIGN.md section 7); never call `fetch` directly for the API.
 * Public responses need no cookies and may be cached (FRONTEND_ARCHITECTURE.md section 3).
 */
const configuration = new Configuration({
  basePath: apiBaseUrl,
  headers: { Accept: "application/json" },
});

export const catalogApi = new CatalogApi(configuration);
export const discoveryApi = new DiscoveryApi(configuration);
export const marketplaceApi = new MarketplaceApi(configuration);

/** Runs an API call; any failure becomes an `ApiError`. */
export async function callApi<T>(call: () => Promise<T>): Promise<T> {
  try {
    return await call();
  } catch (error) {
    throw await toApiError(error, apiBaseUrl);
  }
}

/** Like `callApi`, but a 404 becomes `null` so pages can call `notFound()`. */
export async function callApiOrNull<T>(call: () => Promise<T>): Promise<T | null> {
  try {
    return await callApi(call);
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) {
      return null;
    }
    throw error;
  }
}
